using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Management;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;

namespace Aurora {
public sealed class DriverCleanupPackage {
    public string Inf,Provider,Version,Class;public string[] Devices;public bool Signed,SharedOutsideScope;
    public bool Eligible{get{return Regex.IsMatch(Inf??"",@"^oem\d+\.inf$",RegexOptions.IgnoreCase)&&Signed&&!SharedOutsideScope&&!Regex.IsMatch(Provider??"",@"^Microsoft\b",RegexOptions.IgnoreCase);}}
    public override string ToString(){return Provider+" • "+Version+" • "+Inf+"\n"+String.Join("; ",Devices??new string[0]);}
}
public static class DriverCleanup {
    public static List<DriverCleanupPackage> Read(){var devices=new List<Dictionary<string,string>>();foreach(ManagementObject d in Machine.Query("root\\cimv2","SELECT DeviceName,DriverProviderName,DriverVersion,InfName,DeviceClass,IsSigned FROM Win32_PnPSignedDriver"))using(d){var item=new Dictionary<string,string>();foreach(string key in new[]{"DeviceName","DriverProviderName","DriverVersion","InfName","DeviceClass","IsSigned"})item[key]=Machine.Value(d,key);devices.Add(item);}return devices.Where(x=>Regex.IsMatch(x["DeviceClass"],"^(DISPLAY|MEDIA)$",RegexOptions.IgnoreCase)).GroupBy(x=>x["InfName"],StringComparer.OrdinalIgnoreCase).Select(g=>{var all=devices.Where(x=>x["InfName"].Equals(g.Key,StringComparison.OrdinalIgnoreCase)).ToArray();return new DriverCleanupPackage{Inf=g.Key,Provider=g.First()["DriverProviderName"],Version=g.First()["DriverVersion"],Class=g.First()["DeviceClass"],Devices=all.Select(x=>x["DeviceName"]).Distinct().ToArray(),Signed=all.All(x=>x["IsSigned"].Equals("True",StringComparison.OrdinalIgnoreCase)),SharedOutsideScope=all.Any(x=>!Regex.IsMatch(x["DeviceClass"],"^(DISPLAY|MEDIA)$",RegexOptions.IgnoreCase))};}).Where(x=>x.Eligible).OrderBy(x=>x.Provider).ToList();}
    public static string Remove(DriverCleanupPackage selected,Action<WorkProgress> progress){if(selected==null||!selected.Eligible)throw new InvalidDataException("Invalid driver cleanup selection");var live=Read().FirstOrDefault(x=>x.Inf.Equals(selected.Inf,StringComparison.OrdinalIgnoreCase));if(live==null||!live.Eligible||live.Version!=selected.Version||!live.Devices.OrderBy(x=>x).SequenceEqual(selected.Devices.OrderBy(x=>x)))throw new IOException(L.T("O inventário mudou. Atualize a lista antes de remover.","Inventory changed. Refresh the list before removing."));string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AuroraUtility","DriverBackups",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var pnputil=Path.Combine(Environment.SystemDirectory,"pnputil.exe");if(progress!=null)progress(new WorkProgress{Stage=L.T("Exportando backup do driver","Exporting driver backup")});var export=Runner.Run(pnputil,"/export-driver "+selected.Inf+" "+Args.Q(root),180000);if(export.Code!=0)throw new IOException(L.T("O backup falhou; a remoção não foi iniciada. ","Backup failed; removal was not started. ")+export.Output);var files=Directory.GetFiles(root,"*",SearchOption.AllDirectories);if(!files.Any(x=>Path.GetExtension(x).Equals(".inf",StringComparison.OrdinalIgnoreCase))||!files.Any(x=>Path.GetExtension(x).Equals(".cat",StringComparison.OrdinalIgnoreCase)))throw new IOException(L.T("O backup não contém INF e catálogo; remoção interrompida.","Backup has no INF and catalog; removal stopped."));var manifest=new StringBuilder();foreach(string file in files){if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Redirected backup file");using(var hash=SHA256.Create())using(var input=File.OpenRead(file))manifest.AppendLine(BitConverter.ToString(hash.ComputeHash(input)).Replace("-","")+"  "+file.Substring(root.Length+1));}File.WriteAllText(Path.Combine(root,"SHA256.txt"),manifest.ToString(),Encoding.UTF8);if(progress!=null)progress(new WorkProgress{Stage=L.T("Removendo o pacote selecionado","Removing the selected package")});var removal=Runner.Run(pnputil,"/delete-driver "+selected.Inf+" /uninstall",300000);DriverInventory.Invalidate();return (removal.Code==0?"OK":removal.Code==3010?"OK • Reinicialização necessária":"ERROR "+removal.Code)+"\n"+removal.Output+"\n"+L.T("Backup: ","Backup: ")+root;}
}
public partial class MainWindow {
    void DriverCleanupCard(){var p=Card(T("Limpeza de drivers de vídeo e áudio","Video and audio driver cleanup"),T("Selecione um pacote. Antes da remoção, o OuO exporta uma cópia. Todos os dispositivos que usam o pacote serão afetados.","Select a package. OuO exports a backup before removal. All devices using the package will be affected."));p.Children.Add(Text(T("Recurso em fase de testes • a remoção em hardware físico ainda não foi validada.","Feature in testing • removal on physical hardware has not been validated."),12,Muted));var list=new StackPanel();p.Children.Add(list);var selections=new Dictionary<DriverCleanupPackage,CheckBox>();var output=Input("");output.IsReadOnly=true;output.AcceptsReturn=true;output.TextWrapping=TextWrapping.Wrap;output.Height=170;Action refresh=()=>{List<DriverCleanupPackage> data=null;Work(T("Checar drivers para limpeza","Check drivers for cleanup"),()=>{data=DriverCleanup.Read();return "OK • "+data.Count+T(" pacote(s) encontrado(s)."," package(s) found.");},r=>{list.Children.Clear();selections.Clear();if(data==null){output.Text=r;return;}foreach(var item in data)selections[item]=Choice(list,item.ToString(),true,false);if(data.Count==0)list.Children.Add(Text(T("Nenhum pacote de vídeo/áudio elegível foi encontrado.","No eligible video/audio package was found."),13,Muted));});};Row(p,Button(T("Buscar pacotes instalados","Find installed packages"),refresh),Button(T("Fazer backup e remover selecionados","Back up and remove selected"),()=>{var selected=selections.Where(x=>x.Value.IsChecked==true).Select(x=>x.Key).ToArray();if(selected.Length==0){ShowToast(T("Selecione pelo menos um pacote.","Select at least one package."));return;}if(!RequireAdmin())return;if(!Confirm(T("Remover estes drivers?\n\n","Remove these drivers?\n\n")+String.Join("\n\n",selected.Select(x=>x.ToString()))+T("\n\nA tela pode piscar ou perder a resolução atual, e o áudio pode parar até reinstalar o driver. Tenha o instalador do fabricante disponível. O OuO fará backup antes de cada remoção.","\n\nThe display may flicker or lose its current resolution, and sound may stop until the driver is reinstalled. Have the manufacturer's installer available. OuO backs up each package before removing it.")))return;Work(T("Limpeza de drivers","Driver cleanup"),()=>{var result=new StringBuilder();int done=0;foreach(var item in selected){WorkReporting.Report(done,selected.Length,T("Pacote ","Package ")+item.Inf);try{result.AppendLine(DriverCleanup.Remove(item,WorkReporting.Sink));}catch(Exception ex){result.AppendLine("ERROR • "+item.Inf+" • "+ex.Message);}done++;WorkReporting.Report(done,selected.Length,T("Pacotes processados","Packages processed"));}return result.ToString();},r=>{output.Text=r;refresh();});}));Note(p,"Para uma limpeza profunda com DDU, use o programa oficial seguindo as orientações do fornecedor. O OuO não inclui nem executa uma cópia do motor DDU. Guarde a chave BitLocker antes de procedimentos de recuperação.","For deep cleanup with DDU, use the official program following the vendor's instructions. OuO does not include or execute a copy of the DDU engine. Keep your BitLocker recovery key before recovery procedures.");Row(p,Button(T("DDU oficial e instruções","Official DDU and instructions"),()=>Open("https://www.wagnardsoft.com/content/How-use-Display-Driver-Uninstaller-DDU-Guide-Tutorial")),Button(T("Abrir backups dos drivers","Open driver backups"),()=>{string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AuroraUtility","DriverBackups");Directory.CreateDirectory(folder);Open(folder);}));AttachResult(p,output);}
}
}
